from typing import List, Literal, TypedDict, Unpack

from ...base.client import BaseClient


class PrivacyGroupsInviteBlacklistKwargs(TypedDict):
    cursor: str


class PrivacyMethods(BaseClient):
    """
    Методы группы 'Конфиденциальность' из https://im-docs.corp.mail.ru/
    """

    async def rapi_getPrivacySetting(self) -> dict:
        """
        Запросить общие настройки приватности аккаунта
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/getPrivacySettings",
            json={"aimsid": self.aimsid, "reqId": self.getReqId()},
        )

    async def rapi_setUserAgreement(self, name: str, enable: bool) -> dict:
        """
        Устанавливает или сбрасывает пользовательское соглашение.
        :param name: Название соглашение
        :param enable: Включить или отключить
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/setUserAgreement",
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"name": name, "enable": enable},
            },
        )

    async def rapi_updatePrivacySettings(
        self,
        privacy: Literal["calls", "groups"],
        permission: Literal["everybody", "myContacts", "nobody"],
    ) -> dict:
        """
        Изменить настройку приватности
        :param privacy: изменяемая настройка
        :param permission: на что меняем
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/updatePrivacySettings",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {privacy: {"allowTo": permission}},
            },
        )

    async def rapi_privacy_groups_inviteBlacklist_get(
        self, pageSize: int, **kwargs: Unpack[PrivacyGroupsInviteBlacklistKwargs]
    ) -> dict:
        r"""
        Запросить список пользователей, которым запрещено добавлять
        меня в группы

        :param pageSize: размер страницы
        param cursor: курсор поиска если имеется \n
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/privacy/groups/inviteBlacklist/get",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"pageSize": pageSize, **kwargs},
            },
        )

    async def rapi_privacy_groups_inviteBlacklist_getBlacklistedContacts(
        self,
        pageSize: int = 100,
        **kwargs: Unpack[PrivacyGroupsInviteBlacklistKwargs],
    ) -> dict:
        r"""
        Запросить список пользователей, которым запрещено добавлять
        меня в группы

        :param pageSize: размер страницы
        param cursor: курсор поиска если имеется \n
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/privacy/groups/inviteBlacklist/getBlacklistedContacts",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"pageSize": pageSize, **kwargs},
            },
        )

    async def rapi_privacy_groups_inviteBlacklist_search(
        self,
        keyword: str,
        pageSize: int,
        **kwargs: Unpack[PrivacyGroupsInviteBlacklistKwargs],
    ) -> dict:
        r"""
        Поиск по списку пользователей, которым запрещено добавлять
        меня в группы

        :param keyword: ключевая фраза для поиска
        :param pageSize: Ожидаемое количество результатов в одном ответе.
        param cursor: Курсор, полученный в ответе на предыдущий запрос \n
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/privacy/groups/inviteBlacklist/search",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"keyword": keyword, "pageSize": pageSize, **kwargs},
            },
        )

    async def rapi_privacy_groups_inviteBlacklist_add(self, users: List[str]) -> dict:
        """
        Запретить указанным пользователям добавлять меня в группы

        :param users: список пользователей
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/privacy/groups/inviteBlacklist/add",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"users": users},
            },
        )

    async def rapi_privacy_groups_inviteBlacklist_del(self, users: List[str]) -> dict:
        """
        Разрешить указанным пользователям добавлять меня в группы

        :param users: список пользователей
        :return: тело ответа сервера
        """
        return await self.post(
            "rapi/privacy/groups/inviteBlacklist/del",
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"users": users},
            },
        )
